  'EAS raises the build number on every build': 'EAS menaikkan nomor build di setiap build',
  'Build numbers are set by hand; the stores refuse a number they already have. Set autoIncrement in eas.json':
    'Nomor build diatur manual; toko aplikasi menolak nomor yang sudah ada. Atur autoIncrement di eas.json',
  'App Store Connect app {0}': 'Aplikasi App Store Connect {0}',
  'No App Store Connect app in eas.json (submit.production.ios.ascAppId)':
    'Tidak ada aplikasi App Store Connect di eas.json (submit.production.ios.ascAppId)',
  'Android goes to Play’s internal testing track': 'Android masuk ke jalur pengujian internal Play',
  'eas.json submits Android to the {0} track; Release submits to the internal track only':
    'eas.json mengirim Android ke jalur {0}; Rilis hanya mengirim ke jalur internal',
  'iOS permission texts are set': 'Teks izin iOS sudah diatur',
  'iOS permission texts use the library’s generic wording, which App Review can reject: {0}':
    'Teks izin iOS memakai kalimat umum dari library, yang bisa ditolak App Review: {0}',
  'iOS permission texts are missing, which App Review rejects: {0}':
    'Teks izin iOS belum ada, yang akan ditolak App Review: {0}',
  'Enroll in the Apple Developer Program (a yearly fee) with the Apple account that publishes the app.':
    'Daftar ke Apple Developer Program (biaya tahunan) dengan akun Apple yang menerbitkan aplikasi.',
  'Create the app in App Store Connect with the same bundle identifier, and put its Apple ID in eas.json as submit.production.ios.ascAppId.':
    'Buat aplikasi di App Store Connect dengan bundle identifier yang sama, lalu masukkan Apple ID-nya ke eas.json sebagai submit.production.ios.ascAppId.',
  'Run the first iOS build once in a terminal (eas build --platform ios) and sign in to Apple there, so EAS creates the signing certificate and profile. Later releases reuse them.':
    'Jalankan build iOS pertama sekali di terminal (eas build --platform ios) dan masuk ke Apple di sana, agar EAS membuat sertifikat dan profil penandatanganan. Rilis berikutnya memakainya lagi.',
  'Create the app in Google Play Console with the same package name.':
    'Buat aplikasi di Google Play Console dengan nama paket yang sama.',
  'Upload the first Android build to Play Console by hand: Google accepts uploads through its API only after that.':
    'Unggah build Android pertama ke Play Console secara manual: Google baru menerima unggahan lewat API-nya setelah itu.',
  'Give EAS a Google service account key for submissions (eas credentials, then Android, then Google Service Account).':
    'Berikan kunci service account Google ke EAS untuk pengiriman (eas credentials, lalu Android, lalu Google Service Account).',
  'Invite testers in TestFlight and in Play’s internal testing, fill in each store listing, and submit for review on each store when you are ready. Ramu never submits for review.':
    'Undang penguji di TestFlight dan pengujian internal Play, isi listing tiap toko, lalu ajukan review di tiap toko saat kamu siap. Ramu tidak pernah mengajukan review.',
  Domain: 'Domain',
  User: 'Pengguna',
  'Tell people what shipped': 'Kabarkan yang sudah dirilis',
  'Make a release note': 'Buat catatan rilis',
  'Make a launch deck': 'Buat dek peluncuran',
  'Make a release note as a Doc artifact from the pull requests merged since the last release: what changed for the people who use it, grouped by what they would notice, with each pull request linked.':
    'Buat catatan rilis sebagai artefak Dokumen dari pull request yang digabung sejak rilis terakhir: apa yang berubah bagi orang yang memakainya, dikelompokkan menurut apa yang akan mereka sadari, dengan tautan ke setiap pull request.',
  'Make a short launch deck as a Slides artifact from the pull requests merged since the last release: the problem, what is new, how it looks, and what comes next, with speaker notes.':
    'Buat dek peluncuran singkat sebagai artefak Slide dari pull request yang digabung sejak rilis terakhir: masalahnya, apa yang baru, tampilannya, dan langkah berikutnya, dengan catatan pembicara.',
