  'Presenter notes': 'Catatan presenter',
  'No speaker notes on this slide.': 'Tidak ada catatan pembicara di slide ini.',
  'Edit as formatted text': 'Sunting sebagai teks berformat',
  'Block {number}': 'Blok {number}',
