  Hostname: 'Nama host',
  'Cloudflare token': 'Token Cloudflare',
  'Make the address': 'Buat alamatnya',
  'Give it a lasting address…': 'Beri alamat tetap…',
  'A hostname on a domain in your Cloudflare account, such as demo.example.com. Ramu makes a tunnel that answers only that hostname, at one port of this computer, and its DNS record. The token needs Account → Cloudflare Tunnel → Edit and Zone → DNS → Edit; it stays in this computer’s credential store.':
    'Nama host pada domain di akun Cloudflare-mu, misalnya demo.example.com. Ramu membuat tunnel yang hanya menjawab nama host itu, di satu port komputer ini, beserta record DNS-nya. Token perlu Account → Cloudflare Tunnel → Edit dan Zone → DNS → Edit; token tetap di penyimpanan kredensial komputer ini.',
  'Read it by running expo config': 'Baca dengan menjalankan expo config',
  'Runs the project’s own app.config code on this computer to read the configuration it computes':
    'Menjalankan kode app.config proyek di komputer ini untuk membaca konfigurasi yang dihitungnya',
  'Create a fine-grained token on GitHub': 'Buat token fine-grained di GitHub',
  'Cloudflare token with DNS edit, used once': 'Token Cloudflare dengan DNS edit, dipakai sekali',
  'DNS at Cloudflare? Create them there…': 'DNS di Cloudflare? Buat di sana…',
  'Next: push {0}, or merge a pull request into it, and the platform builds the first deployment. The project’s latest thread hears how it went.':
    'Berikutnya: push {0}, atau gabungkan pull request ke sana, dan platform membangun deployment pertama. Thread terbaru proyek diberi tahu hasilnya.',
  'The first deployment is building…': 'Deployment pertama sedang dibangun…',
  'The first deployment failed. Logs shows why; the project’s latest thread was told.':
    'Deployment pertama gagal. Lihat sebabnya di Log; thread terbaru proyek sudah diberi tahu.',
  'Run the migrations before each production build goes live: the platform holds every finished build, Ramu runs the migrate command from ramu.json against production at that commit, and only then makes it live. A failed migration leaves the previous build live. This computer must be awake for production deploys.':
    'Jalankan migrasi sebelum setiap build produksi tayang: platform menahan setiap build yang selesai, Ramu menjalankan perintah migrate dari ramu.json terhadap produksi pada commit itu, lalu baru menayangkannya. Migrasi yang gagal membuat build sebelumnya tetap tayang. Komputer ini harus menyala untuk deploy produksi.',
  '{0}% on the sample tasks': '{0}% pada tugas contoh',
  Subscription: 'Langganan',
  'API key, cost not reported': 'API key, biaya tidak dilaporkan',
  'About {0} a call': 'Sekitar {0} per panggilan',
  'chosen as the cheapest good enough': 'dipilih sebagai yang termurah dan cukup baik',
  'Pull request previews': 'Preview pull request',
  'Each pull request is published as an EAS Update, with a QR code on the pull request.':
    'Setiap pull request diterbitkan sebagai EAS Update, dengan kode QR di pull request.',
  'Each pull request can be published as an EAS Update with a QR code to open it on a phone. The app needs these first:':
    'Setiap pull request bisa diterbitkan sebagai EAS Update dengan kode QR untuk membukanya di ponsel. Aplikasi perlu ini dulu:',
  'The pull request adding the preview job is open. Merge it, and later pull requests get a QR code.':
    'Pull request yang menambahkan job preview sudah dibuka. Gabungkan, dan pull request berikutnya mendapat kode QR.',
  'The QR code opens a development build of the app, since it uses expo-dev-client; install one on the phone first.':
    'Kode QR membuka development build aplikasi, karena aplikasi memakai expo-dev-client; pasang dulu di ponsel.',
  'The QR code opens the update in Expo Go. A change to native code still needs a new build.':
    'Kode QR membuka update di Expo Go. Perubahan kode native tetap memerlukan build baru.',
  'Add previews in a pull request': 'Tambahkan preview lewat pull request',
  'expo-updates is not installed: npx expo install expo-updates':
    'expo-updates belum dipasang: npx expo install expo-updates',
  'No runtimeVersion in app.json: eas update:configure sets it':
    'Tidak ada runtimeVersion di app.json: eas update:configure mengaturnya',
  'No updates.url in app.json: eas update:configure sets it':
    'Tidak ada updates.url di app.json: eas update:configure mengaturnya',
