  "Write to Git config": "Tulis ke konfigurasi Git",
  "Sets user.name and user.email in its repositories, for commits made outside Ramu.": "Mengatur user.name dan user.email di repositorinya, untuk commit yang dibuat di luar Ramu.",
  "A host or phone that has your backup key shows the same number; approve there.": "Host atau ponsel yang punya kunci cadangan Anda menampilkan angka yang sama; setujui di sana.",
  "A listed host can be added from your other signed-in devices without a code; it still asks you to approve each one. The account learns its name, never its address.": "Host yang terdaftar bisa ditambahkan dari perangkat lain yang sudah masuk tanpa kode; host tetap meminta persetujuan Anda untuk masing-masing. Akun hanya tahu namanya, tidak pernah alamatnya.",
