  "Appearance, text size, language, themes and layout, sealed on this phone. Paired hosts and drafts are never included.": "Tampilan, ukuran teks, bahasa, tema, dan tata letak, disegel di ponsel ini. Host yang dipasangkan dan draf tidak pernah ikut.",
