  "Earlier: {time}": "Sebelumnya: {time}",
  "Every backup, listed host and sign-in in the account is deleted at once. Settings on your hosts stay as they are.": "Semua cadangan, host terdaftar, dan sesi masuk di akun dihapus sekaligus. Pengaturan di host Anda tetap seperti sekarang.",
  "Find backups": "Cari cadangan",
  "From a backup another of your hosts or this one made. Nothing changes until you review it.": "Dari cadangan yang dibuat host Anda yang lain atau host ini. Tidak ada yang berubah sampai Anda meninjaunya.",
