  "It should show {code}": "Seharusnya menampilkan {code}",
  "Keep this code in a password manager. With it, a new machine opens your backups even when every other device is gone. Without any device and without the code, the backups cannot be opened, by you or by anyone.": "Simpan kode ini di pengelola kata sandi. Dengan kode ini, mesin baru bisa membuka cadangan Anda meski semua perangkat lain hilang. Tanpa perangkat dan tanpa kode, cadangan tidak bisa dibuka, oleh Anda maupun siapa pun.",
