  "Open Settings → Account on a device you have.": "Buka Pengaturan → Akun di perangkat yang Anda punya.",
  "Optional. It keeps backups only your devices can open and lists your hosts, and never gives access to a host. Run by Akalstack.": "Opsional. Menyimpan cadangan yang hanya bisa dibuka perangkat Anda dan mendaftar host Anda, serta tidak pernah memberi akses ke host. Dijalankan oleh Akalstack.",
  "Optional. It keeps settings backups that only your devices can open, and lists your hosts so a signed-in device can ask to pair without a code. The account is run by Akalstack and never gives access to a host.": "Opsional. Menyimpan cadangan pengaturan yang hanya bisa dibuka perangkat Anda, dan mendaftar host Anda agar perangkat yang sudah masuk bisa meminta pemasangan tanpa kode. Akun dijalankan oleh Akalstack dan tidak pernah memberi akses ke host.",
