  "Bring theme, models, rules and identities from a backup or another of your hosts. Nothing changes until you review it.": "Bawa tema, model, aturan, dan identitas dari cadangan atau host Anda yang lain. Tidak ada yang berubah sampai Anda meninjaunya.",
