  "Token": "Token",
  "Connect GitLab": "Hubungkan GitLab",
  "Create a fine-grained token limited to the repositories you need; the page opens with the permissions Ramu uses chosen. For GitHub Enterprise, change the server first.": "Buat token fine-grained yang dibatasi pada repositori yang Anda perlukan; halamannya terbuka dengan izin yang dipakai Ramu sudah dipilih. Untuk GitHub Enterprise, ubah servernya dulu.",
  "Create a personal access token with Code (read and write), Build (read) and Work Items (read) scopes in the organization.": "Buat personal access token dengan cakupan Code (baca dan tulis), Build (baca) dan Work Items (baca) di organisasi itu.",
  "Create a personal access token with the api scope on your GitLab server; the page opens with it chosen. For a self-managed server, change the server first.": "Buat personal access token dengan cakupan api di server GitLab Anda; halamannya terbuka dengan cakupan itu sudah dipilih. Untuk server self-managed, ubah servernya dulu.",
  "Create an Atlassian API token with Bitbucket scopes for repositories, pull requests, pipelines and issues, then paste it here with the email of that account.": "Buat token API Atlassian dengan cakupan Bitbucket untuk repositori, pull request, pipeline dan issue, lalu tempel di sini bersama email akun itu.",
  "Create token on Atlassian": "Buat token di Atlassian",
  "Create token on Azure DevOps": "Buat token di Azure DevOps",
  "Create token on GitHub": "Buat token di GitHub",
  "Create token on GitLab": "Buat token di GitLab",
  "Fill in {0} first": "Isi {0} dulu",
  "It covers pull requests, issues and checks; Git push and fetch keep using your own Git credentials.": "Token ini mencakup pull request, issue dan pemeriksaan; push dan fetch Git tetap memakai kredensial Git Anda sendiri.",
  "Leave empty for a workspace or repository access token.": "Kosongkan untuk access token workspace atau repositori.",
  "Not connected. Connect to work with pull requests, builds and issues.": "Belum terhubung. Hubungkan untuk bekerja dengan pull request, build dan issue.",
  "Not connected. Connect to work with pull requests, builds and work items.": "Belum terhubung. Hubungkan untuk bekerja dengan pull request, build dan work item.",
  "Paste the token": "Tempel tokennya",
