  "Sign in with glab instead": "Masuk dengan glab saja",
  "Use the GitLab CLI?": "Pakai GitLab CLI?",
  "Tagged New in the model list.": "Ditandai Baru di daftar model.",
  "The host checks the token, keeps it in its credential store and sends it only to {0}.": "Host memeriksa token, menyimpannya di penyimpanan kredensialnya dan hanya mengirimnya ke {0}.",
