  "{0} more": "{0} lainnya",
  "{0} new models": "{0} model baru",
  "Accounts connect on one host. Choose a host in the settings header to connect or change them.": "Akun terhubung di satu host. Pilih host di header pengaturan untuk menghubungkan atau mengubahnya.",
  "Model control": "Kontrol model",
