  "Choose who you commit as": "Pilih identitas untuk commit",
  "Each project acts as an identity, picked from its folder or remote: its commits and accounts follow it.": "Setiap proyek bertindak sebagai satu identitas, dipilih dari folder atau remote-nya: commit dan akunnya mengikuti identitas itu.",
  "Give each identity its own name.": "Beri setiap identitas nama sendiri.",
  "Add the name your commits show.": "Tambahkan nama yang tampil di commit Anda.",
